// TH15 synthetic training aliases (subset used by this card).
// Source etSprite type16 -> TH15_STAR_R (target row base 608, radius 4, colors 0-15).
const TH15_STAR_R: int = 608;

// TH15 v1.00b st05.ecl::MainSub08 (entry) 1666-1720, with GirlD05 1226-1237,
// GirlD05_at 1239-1254, GirlD05_at2 1256-1292.
// Source t0 = MainSub08 selected entry (line1666); card t0 = phase start, opening 120.
// Chapter/queue gates and drops/presentation omitted per TH15 policy; real rank sampling kept.
const TIME_LIMIT: int = 1424;
const OPENING_BUFFER: int = 120;

// Source VELTIME EX: etEx(0,0,0x200000,120,-999999,r=4E/8NHL,-999999) ramps scalar speed
// from 0 to target over a=120 along the spawn angle (s sentinel -> keep angle).
// Birth ANIM (record 0, a=1) omitted by policy; spawn speed is 0 so its retreat is 0.
xformdef SPEED_RAMP(target: fx) {
    step_speed(target, 120);
}

// GirlD05_at 1239-1254: ABS polar move; source mode1 = quad-in, mode0 = linear.
// enmCreateM mirror is resolved per side at the write point (enemy-state: mirror is not
// auto-applied to fire angles, only to movement angle): right uses pi-theta.
async sub girl05(i1: int, vt: fx, f0: angle, f1: angle, mv1: angle, mv2: angle) {
    set_invuln(65535);
    set_hurtbox(12fx); // source setHurtbox(24,24): ordinary circle radius = 24*0.5
    set_hitbox(8fx);   // source setHitbox(16,16): ordinary circle radius = 16*0.5
    move_vel(0, 16384bam, 3fx, EASE_LINEAR);     // source moveVel(pi/2, 3.0)
    move_vel(60, mv1, 0fx, EASE_QUAD_IN);        // source moveVelTime(60,1,mv1,0.0)
    spawn firing(i1, vt, f0, f1);                // source @GirlD05_at2() async
    wait(40);
    move_vel(60, mv2, 4fx, EASE_LINEAR);         // source moveVelTime(60,0,mv2,4.0)
    loop { wait(1000); }                         // source wait(1000) loop; engine culls offscreen
}

// GirlD05_at2 1256-1292: mode3 fixed-direction ring, 8x1, etSpeed(0,1) M=1 -> 0.
// Every frame A += F1; on (B%20)>=I1 re-aim the ring base to A and fire.
async sub firing(i1: int, vt: fx, f0: angle, f1: angle) {
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, 2); // source type16 color2
    sh_ring(0, 1);                // source etAim(0,3): full ring
    sh_aim(0, 0);                 // fixed direction
    sh_count(0, 8, 1);            // source etCount(0,8,1)
    sh_speed(0, 0fx, 0fx);        // source etSpeed(0,0,1): M=1 -> s0
    sh_xform(0, SPEED_RAMP(vt));
    var a: angle = f0;
    var b: int = -1;
    var c: int = 3000;
    while c != 0 {
        b = b + 1;
        if (b % 20) >= i1 {
            sh_angle(0, a, 0deg); // source etAngle(0,A,45deg); 45deg is inert at 1 layer
            sh_fire(0);
        }
        a = a + f1;
        wait(1);
        c = c - 1;
    }
}

