    // 1702-1713 group3 diffI(15,6,4,3)
    i1 = 3; if rank == 0 { i1 = 15; } if rank == 1 { i1 = 6; } if rank == 2 { i1 = 4; }
    _ = spawn_enemy(-128fx, -48fx, 300, 0, 1000, 0, girl05(i1, vt, 8192bam, 146bam, 14336bam, -2048bam));
    wait(70);
    _ = spawn_enemy(128fx, -48fx, 300, 0, 1000, 0, girl05(i1, vt, 24576bam, -146bam, 18432bam, 34816bam));
